#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <numeric>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long q;
    cin >> n >> q;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];
    vector<vector<long long>> qs(q, vector<long long>(2));
    for (int i = 0; i < q; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> qs[i][j];
        }
    }

    sort(a.begin(), a.end());
    vector<int> order(q);
    for (int i = 0; i < q; i++) order[i] = i;
    sort(order.begin(), order.end(), [&](int x, int y) { return qs[x][1] < qs[y][1]; });
    vector<int> child0(1, 0), child1(1, 0);
    auto insertNumber = [&](long long x) {
        int node = 0;
        for (int b = 29; b >= 0; b--) {
            vector<int>& child = ((x >> b) & 1) ? child1 : child0;
            if (child[node] == 0) {
                child0.push_back(0);
                child1.push_back(0);
                child[node] = (int)child0.size() - 1;
            }
            node = child[node];
        }
    };
    auto bestXor = [&](long long x) {
        int node = 0;
        long long result = 0;
        for (int b = 29; b >= 0; b--) {
            int bit = (int)((x >> b) & 1);
            vector<int>& want = bit ? child0 : child1;
            if (want[node] != 0) {
                result |= 1LL << b;
                node = want[node];
            } else {
                node = (bit ? child1 : child0)[node];
            }
        }
        return result;
    };
    vector<long long> answers(q, -1);
    int j = 0;
    for (int i : order) {
        while (j < n && a[j] <= qs[i][1]) {
            insertNumber(a[j]);
            j++;
        }
        if (j > 0) answers[i] = bestXor(qs[i][0]);
    }
    for (long long value : answers) cout << value << "\n";

    return 0;
}

