import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long q = Long.parseLong(next());
        long[] a = new long[(int) n];
        for (int i = 0; i < a.length; i++) a[i] = Long.parseLong(next());
        long[][] qs = new long[(int) q][2];
        for (int i = 0; i < qs.length; i++) {
            for (int j = 0; j < qs[i].length; j++) {
                qs[i][j] = Long.parseLong(next());
            }
        }

        Arrays.sort(a);
        int count = (int) n, queries = (int) q;
        Integer[] order = new Integer[queries];
        for (int i = 0; i < queries; i++) order[i] = i;
        Arrays.sort(order, (x, y) -> Long.compare(qs[x][1], qs[y][1]));
        int[] child0 = new int[count * 30 + 2];
        int[] child1 = new int[count * 30 + 2];
        int nodes = 1;
        long[] answers = new long[queries];
        Arrays.fill(answers, -1);
        int j = 0;
        for (int i : order) {
            while (j < count && a[j] <= qs[i][1]) {
                int node = 0;
                for (int b = 29; b >= 0; b--) {
                    int[] child = ((a[j] >> b) & 1) != 0 ? child1 : child0;
                    if (child[node] == 0) child[node] = nodes++;
                    node = child[node];
                }
                j++;
            }
            if (j > 0) {
                long x = qs[i][0];
                int node = 0;
                long result = 0;
                for (int b = 29; b >= 0; b--) {
                    int bit = (int) ((x >> b) & 1);
                    int[] want = bit != 0 ? child0 : child1;
                    if (want[node] != 0) {
                        result |= 1L << b;
                        node = want[node];
                    } else {
                        node = (bit != 0 ? child1 : child0)[node];
                    }
                }
                answers[i] = result;
            }
        }
        StringBuilder out = new StringBuilder();
        for (long value : answers) out.append(value).append("\n");
        System.out.print(out);
    }
}
